 async function database(name,store){return new Promise((yes,no)=>{const r=indexedDB.open(name,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(store))r.result.createObjectStore(store);};r.onsuccess=()=>yes(r.result);r.onerror=()=>no(r.error);});}
