 async function migrateCredits(value){const d=JSON.parse(value);let changed=false;for(const n of d.creditNotes||[])if(n.pdfBase64){n.pdfId=await jmConserverPdf('credit',n.number,new Blob([Uint8Array.from(atob(n.pdfBase64),c=>c.charCodeAt(0))],{type:'application/pdf'}));delete n.pdfBase64;changed=true;}return changed?JSON.stringify(d):value;}
