 async function backup(){if(working)return;working=true;try{let bg=$('jmBackupBg');bg?.remove();bg=document.createElement('div');bg.id='jmBackupBg';bg.className='modal-bg show';bg.innerHTML='<div class="modal"><h2>Sauvegarder mes données</h2><p>Deux ZIP à conserver dans Fichiers. Taille estimée avant création ; plafond de 150 Mo par archive pour limiter la mémoire utilisée sur iPhone.</p><p id="jmBackupStatus" role="status">Estimation…</p><div id="jmBackupChoices"></div><button class="ghost" id="jmBackupClose">Fermer</button></div>';document.body.append(bg);$('jmBackupClose').onclick=()=>{if(!working)bg.remove();};for(const [kind,label] of [['data','Données + tickets + photos'],['videos','Vidéos']]){const plan=await backupPlan(kind),p=document.createElement('p'),button=document.createElement('button');p.textContent=label+' : environ '+mb(plan.size)+(plan.size>ARCHIVE_LIMIT?' — dépasse le plafond de 150 Mo':'');button.type='button';button.className='primary';button.textContent='Créer le ZIP — '+label;button.disabled=plan.size>ARCHIVE_LIMIT;button.onclick=()=>createBackup(kind);$('jmBackupChoices').append(p,button);} $('jmBackupStatus').textContent='Choisis une archive. Pour une sauvegarde complète, conserve les deux ZIP.';}catch(e){showToast('Estimation impossible : '+e.message);}finally{working=false;}}
 // v329 — sauvegarde : fichier préparé ≠ partage effectué ≠ fichier conservé.
