  try{$('jmBackupStatus').textContent='Préparation du ZIP…';plan=await backupPlan(kind);if(plan.size>ARCHIVE_LIMIT)throw Error('Cette archive dépasse 150 Mo. Elle n’a pas été créée : sauvegarde tes médias par lots avant de réessayer.');blob=await JMFuel.zip(plan.entries);if(blob.size>ARCHIVE_LIMIT)throw Error('Archive supérieure à 150 Mo');}
