 window.jmFuelExport=async function(){const button=$('fuelExport');button.disabled=true;try{const year=$('fuelYear').value,rows=(await JMFuel.registry()).filter(f=>String(f.paye).startsWith(year));if(!rows.length)throw Error('Aucun frais pour cette année');const entries=[],missing=[],table=[['Date','Catégorie','Libellé','Montant EUR','Litres','Prix au litre','Station','Référence','Pièce jointe']];for(let i=0;i<rows.length;i++){const f=rows[i];let path='';if(f.justificatif){const ticket=await JMFuel.fileStore('get',f.justificatif.id);if(ticket){path='tickets/'+String(i+1).padStart(4,'0')+'-'+safe(f.paye)+'.'+safe(ticket.ext);entries.push([path,ticket.blob]);}else missing.push(f.paye+' : '+(f.station||f.libelle));}else if(f.categorie==='gasoil')missing.push(f.paye+' : '+(f.station||f.libelle));table.push([csvDate(f.paye),f.categorie,f.libelle,Number(f.montant),f.litres?Number(f.litres):'',f.prixL?{numeric:Number(f.prixL),decimals:3}:'',f.station,f.reference,path||'Ticket manquant']);}entries.push(['releve-frais-'+year+'.csv',csv(table)],['releve-frais-'+year+'.pdf',report('JM Express — Frais '+year,rows.map(f=>csvDate(f.paye)+' | '+f.libelle+' | '+fmt(f.montant)))],['A-LIRE.txt',new Blob(['Frais JM Express '+year+'\nCSV UTF-8, séparateur point-virgule, virgule décimale ; dates JJ/MM/AAAA. Dans Excel, importer avec la région Français (Belgique) si nécessaire.\nTickets manquants :\n'+(missing.join('\n')||'Aucun')])]);await saveBlob(await JMFuel.zip(entries),'JM-Express-Comptabilite-'+year+'.zip');}catch(e){showToast(e.message);}finally{button.disabled=false;}};
